head.script:
scwin.onpageload = function () {

};

scwin.onpageunload = function () {

};

scwin.getType = function (info) {

    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo;


    if (dataList1.getCellData(rowIndex, "col2") == 1) {
        returnInfo = {
            id: "dynamic_select_" + rowIndex + "_" + colIndex,
            inputType: "select",
            options: {
                viewType: "icon"
            },
            itemSet: {
                nodeset: "data:dataList2",
                label: "col1",
                value: "col2"
            }
        };

    } else if (dataList1.getCellData(rowIndex, "col2") == 0) {
        returnInfo = {
            id: "dynamic_select_" + rowIndex + "_" + colIndex,
            inputType: "autoComplete",
            itemSet: {
                nodeset: "data:dataList2",
                label: "col1",
                value: "col2"
            }
        };
    } else {
        returnInfo = {
            id: "dynamic_text_" + rowIndex + "_" + colIndex,
            inputType: "text",
            options: {
            }
        };

    }

    if (returnInfo) {
        console.log("[typeGetter] (" + rowIndex + ", " + colIndex + ") : " + returnInfo.inputType);
    }

    return returnInfo;
};

// 행삭제 버튼 onclick
scwin.trigger2_onclick = function (e) {
    dataList1.removeRow(0);
    console.log("dataList1.removeRow(0)");
};

// 함수실행 버튼 onclick
scwin.trigger3_onclick = function (e) {
    /* 하기 함수 실행 후 행삭제 버튼으로 적용된 row의 윗 row를 삭제할 경우 적용내용이 롤백됨 */
    grd.setCellAllowChar(2, 1, "a-zA-Z");
    grd.setCellDisableEdit(2, 1, true);
    grd.setCellCustomFormatter(5, 1, "scwin.customFormatter");
    grd.setCellDataType(6, 1, "number");
    // grd.setCellDisplayFormat(6, 1, "#,###.00");
    grd.setCellDisplayFormatter(6, 1, "scwin.displayFormatterTest");
    grd.setCellMaxLength(6, 1, 5);
};

scwin.customFormatter = function (data, formattedData, rowIndex, colIndex) {
    console.log("data : " + data);
    console.log("formattedData : " + formattedData);
    formattedData = "custom-" + data;

    return formattedData;
}

scwin.displayFormatterTest = function (value) {
    return "displayFormatterTest-" + value;
};
